{"fingerprint":"0238bcc824390d1fd26bb0cdbc40727bb060d907205f9ed44bdcead226e99748","path":"src/review_gauntlet/checkpoint.py","rule_id":"test-evidence","content":"The `_dirty_review_universe_paths` and `_get_all_uncommitted_paths` functions are near-duplicates (lines 215-232 vs 235-241). They both run the same three git commands. The only difference is that the first filters by review-universe membership and excludes `.review-gauntlet/` paths. Consider extracting the shared git-status gathering into a single helper and applying filters in the callers to reduce duplication and ensure consistency if the git queries ever need updating.","suggestion_code":"def _all_uncommitted_names(root: Path) -> tuple[str, ...]:
    if not (root / ".git").exists():
        return ()
    names = _split(_git(root, "diff", "--name-only", "--cached"))
    names += _split(_git(root, "diff", "--name-only"))
    names += _split(_git(root, "ls-files", "--others", "--exclude-standard"))
    return tuple(sorted({name for name in names}))


def _dirty_review_universe_paths(root: Path) -> tuple[str, ...]:
    from review_gauntlet.inventory import should_include_review_relative_path

    return tuple(
        name
        for name in _all_uncommitted_names(root)
        if not name.startswith(".review-gauntlet/")
        and should_include_review_relative_path(name)
    )


def _get_all_uncommitted_paths(root: Path) -> tuple[str, ...]:
